import{_ as s,o as t,c as a,a3 as o}from"./chunks/framework.CCylkYel.js";const v=JSON.parse('{"title":"Racks and devices","description":"","frontmatter":{},"headers":[],"relativePath":"developers/commands/racks.md","filePath":"developers/commands/racks.md"}'),d={name:"developers/commands/racks.md"};function c(n,e,r,i,p,l){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="racks-and-devices" tabindex="-1">Racks and devices <a class="header-anchor" href="#racks-and-devices" aria-label="Permalink to &quot;Racks and devices&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32 --loopback repl</span></span>
<span class="line"><span>s32&gt; rack list</span></span>
<span class="line"><span>s32&gt; rack rename 0 Lead</span></span>
<span class="line"><span>s32&gt; device add 0 step-seq</span></span>
<span class="line"><span>s32&gt; device list 0</span></span>
<span class="line"><span>s32&gt; stepseq set 0 1 step 0 active=1 note=60 vel=100</span></span>
<span class="line"><span>s32&gt; stepseq get 0 1</span></span>
<span class="line"><span>s32&gt; rack duplicate 0 1</span></span>
<span class="line"><span>s32&gt; rack set 1 bypass=on</span></span></code></pre></div><p><code>RACK</code> and <code>DEV</code> are positions: rack <code>0</code> is the first <a href="/racks/">rack</a>, device <code>0</code> the first device in it. Ids (<code>rack list</code>, <code>device list</code>) are used only by <code>lfo assign</code> and <code>macro set … mode=device</code>.</p><h2 id="racks" tabindex="-1">Racks <a class="header-anchor" href="#racks" aria-label="Permalink to &quot;Racks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>rack list</code></td><td>Position, id, bypass, device count and name of each rack. An empty slot&#39;s id prints <code>-</code></td></tr><tr><td><code>rack rename RACK NAME</code></td><td>Keeps the first 10 characters</td></tr><tr><td><code>rack set RACK bypass=on|off</code></td><td>Bypasses the whole rack</td></tr><tr><td><code>rack clear RACK</code></td><td>Asks first. Removes every device</td></tr><tr><td><code>rack duplicate SRC DST</code></td><td>Asks first. Overwrites the destination rack</td></tr></tbody></table><h2 id="devices" tabindex="-1">Devices <a class="header-anchor" href="#devices" aria-label="Permalink to &quot;Devices&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>device list RACK</code></td><td>Position, type, id and name of each device</td></tr><tr><td><code>device add RACK TYPE</code></td><td>Adds a <a href="/devices/">device</a> to the rack. <code>TYPE</code> is a name (<code>midi-in</code>, <code>midi-out</code>, <code>clock</code>, <code>arp</code>, <code>step-seq</code>, …) or its number from <code>schema</code></td></tr><tr><td><code>device remove RACK DEV</code></td><td>Removes the device. Its LFO assignments and external MIDI mappings are removed; a knob macro on it keeps its rack and shows SET TARGET. MIDI IN or CLOCK in first place stays while other devices are in the rack.</td></tr><tr><td><code>device move RACK FROM TO</code></td><td>Reorders inside the rack. MIDI IN stays first, MIDI OUT last</td></tr><tr><td><code>device param get RACK DEV PARAM</code></td><td>Value and range</td></tr><tr><td><code>device param set RACK DEV PARAM=VALUE [PARAM=VALUE …]</code></td><td>One or more settings in one sentence. Rounded to a whole number and clamped to the range</td></tr><tr><td><code>device param action RACK DEV PARAM</code></td><td>Presses that row&#39;s button, like Select on the panel: <code>randomize</code> (Step Seq), <code>record</code> or <code>reset</code> (Looper), or a <code>PARAM</code> number. A normal row answers <code>BadRequest</code></td></tr><tr><td><code>device host-device RACK DEV</code></td><td>Which USB Host device a MIDI IN or MIDI OUT uses: <code>ALL</code> or a device name</td></tr><tr><td><code>device host-device RACK DEV host=all|N|NAME</code></td><td>Picks ALL, or a device from <code>host-device list</code> by number or name. The name runs to the end of the line, so it can hold spaces</td></tr></tbody></table><p>An empty rack takes <strong>MIDI IN</strong> or <strong>CLOCK</strong> first. A device that can&#39;t go there, or a full rack, answers <code>BadRequest</code>. <code>NoSpace</code> means the S32 has no room for another device.</p><p><code>PARAM</code> is a parameter name (<code>bypass</code>, <code>mode</code>, <code>rate</code>, <code>gate</code>, <code>clock-division</code>, <code>port</code>, <code>host-device</code>, …) or its number from <code>schema</code>, not the row on the screen.</p><h2 id="usb-host-devices" tabindex="-1">USB Host devices <a class="header-anchor" href="#usb-host-devices" aria-label="Permalink to &quot;USB Host devices&quot;">​</a></h2><p><code>host-device list</code> prints the devices this project knows on the <a href="/concepts/routing#usb-host">USB HOST port</a>, numbered as <strong>HOST DEVICE</strong> counts them (<code>0</code> is <strong>ALL</strong>). A device you unplugged stays listed, marked <code>(unplugged)</code>. <code>stored</code> is the name exactly as the project keeps it, in the case the device reported; it is left out when the device has no name. <code>device host-device</code> matches the panel text, not <code>stored</code>, so pick a second identical device by its number.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; host-device list</span></span>
<span class="line"><span>host devices: 4 of 8</span></span>
<span class="line"><span>  0 ALL</span></span>
<span class="line"><span>  1 KEYBOARD  (1209:0001 at 011)  stored &quot;Keyboard&quot;</span></span>
<span class="line"><span>  2 KEYBOARD (2) (unplugged)  (1209:0001 at 012)  stored &quot;Keyboard&quot;</span></span>
<span class="line"><span>  3 SYNTH (unplugged)  (1209:0002 at 021)  stored &quot;Synth&quot;</span></span>
<span class="line"><span>  4 1209:0003  (1209:0003 at 031)</span></span>
<span class="line"><span>s32&gt; device host-device 0 0 host=keyboard</span></span>
<span class="line"><span>rack 0 device 0 HOST DEVICE = KEYBOARD</span></span></code></pre></div><p><strong>HOST DEVICE</strong> only does something while that MIDI IN or MIDI OUT has <strong>PORT</strong> set to <strong>USB HOST</strong>.</p><p>IN SNAPSHOT and ALLOW MORPH for device parameters are under <a href="./snapshots#in-snapshot"><code>snapshot flags</code></a>.</p><h2 id="step-seq" tabindex="-1">Step Seq <a class="header-anchor" href="#step-seq" aria-label="Permalink to &quot;Step Seq&quot;">​</a></h2><p><code>stepseq get RACK DEV</code> prints all 16 steps. <code>DEV</code> must be a Step Seq.</p><p><code>stepseq set RACK DEV step N key=value …</code> changes one step (<code>0</code>–<code>15</code>). Keys: <code>active</code>, <code>note</code>, <code>vel</code>, <code>gate</code>, <code>ch</code>, <code>prob</code>.</p><h2 id="output-after-a-set" tabindex="-1">Output after a set <a class="header-anchor" href="#output-after-a-set" aria-label="Permalink to &quot;Output after a set&quot;">​</a></h2><p><code>rack rename</code> and <code>rack set</code> print the rack&#39;s row, <code>device param set</code> one line per parameter, <code>device host-device ... host=</code> the HOST DEVICE and <code>stepseq set</code> the pattern (<a href="./session#a-set-prints-the-state-it-left">A set prints the state it left</a>):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ s32 --loopback rack rename 0 Lead</span></span>
<span class="line"><span>rack 0 renamed</span></span>
<span class="line"><span>  [0] id=100  bypass=off in=yes devices=1 Lead</span></span>
<span class="line"><span>$ s32 --loopback device param set 0 0 port=4</span></span>
<span class="line"><span>rack 0 device 0 param port (149) set</span></span>
<span class="line"><span>rack 0 device 0 param port (149) = 4.000 (0.000..127.000)</span></span>
<span class="line"><span>$ s32 --loopback device host-device 0 0 host=all</span></span>
<span class="line"><span>rack 0 device 0 HOST DEVICE = ALL</span></span>
<span class="line"><span>rack 0 device 0 HOST DEVICE = ALL</span></span></code></pre></div><p><code>device host-device</code> already read the HOST DEVICE back, so the same line prints twice: your confirmation, then the read-back.</p><p>With <code>--json</code>, <code>device param get</code> and <code>device param set</code> print one object with a <code>params</code> array (one entry per parameter, in the order given). <code>device host-device --json</code> is <code>{&quot;rack&quot;:0,&quot;device&quot;:0,&quot;host&quot;:&quot;ALL&quot;,&quot;value&quot;:0,&quot;connected&quot;:true,&quot;listed&quot;:true}</code>: <code>host</code> is the stored name without <code> (unplugged)</code> (or <code>null</code> for a number the list does not hold), <code>connected</code> is <code>false</code> exactly when the text says <code>(unplugged)</code>, and <code>listed</code> is <code>false</code> exactly for <code>(not listed)</code>.</p>`,22)])])}const u=s(d,[["render",c]]);export{v as __pageData,u as default};
